class Studio_PDF_Engine {private $pages=array('');private $page=0;private $w=595;private $h=842;public function __construct($o='portrait'){if($o==='landscape'){$this->w=842;$this->h=595;}}public function add_page(){$this->pages[]='';$this->page=count($this->pages)-1;}private function op($s){$this->pages[$this->page].=$s;}private function enc($s){$s=iconv('UTF-8','Windows-1252//TRANSLIT',(string)$s);return str_replace(array('\\','(',')'),array('\\\\','\\(','\\)'),$s);}public function color($h){$h=ltrim($h,'#');$r=hexdec(substr($h,0,2))/255;$g=hexdec(substr($h,2,2))/255;$b=hexdec(substr($h,4,2))/255;$this->op(sprintf('%.3f %.3f %.3f rg %.3f %.3f %.3f RG ',$r,$g,$b,$r,$g,$b));}public function rect($x,$y,$w,$h,$f=true){$this->op(sprintf('%.2f %.2f %.2f %.2f re %s ',$x,$this->h-$y-$h,$w,$h,$f?'f':'S'));}public function line($a,$b,$c,$d){$this->op(sprintf('%.2f %.2f m %.2f %.2f l S ',$a,$this->h-$b,$c,$this->h-$d));}public function text($x,$y,$t,$z=10,$bold=false,$c='#1e293b'){$this->color($c);$f=$bold?'F2':'F1';$this->op("BT /$f $z Tf $x ".($this->h-$y)." Td (".$this->enc($t).") Tj ET ");}public function wrapped($x,$y,$t,$w,$z=10,$l=14,$b=false,$c='#1e293b'){$n=max(12,(int)($w/($z*.52)));foreach(preg_split('/\R/',(string)$t) as $p){foreach(explode("\n",wordwrap(trim($p),$n,"\n",true)) as $q){$this->text($x,$y,$q,$z,$b,$c);$y+=$l;}$y+=$l/3;}return $y;}public function output(){$n=count($this->pages);$ps=3;$cs=$ps+$n;$f1=$cs+$n;$f2=$f1+1;$m=$f2;$o=array();$o[1]='<</Type/Catalog/Pages 2 0 R>>';$k=array();for($i=0;$i<$n;$i++)$k[]=($ps+$i).' 0 R';$o[2]='<</Type/Pages/Kids['.implode(' ',$k).']/Count '.$n.'>>';for($i=0;$i<$n;$i++){$po=$ps+$i;$co=$cs+$i;$st=$this->pages[$i];$o[$po]='<</Type/Page/Parent 2 0 R/MediaBox[0 0 '.$this->w.' '.$this->h.']/Resources<</Font<</F1 '.$f1.' 0 R/F2 '.$f2.' 0 R>>>>/Contents '.$co.' 0 R>>';$o[$co]='<</Length '.strlen($st).">> stream\n$st\nendstream";}$o[$f1]='<</Type/Font/Subtype/Type1/BaseFont/Helvetica/Encoding/WinAnsiEncoding>>';$o[$f2]='<</Type/Font/Subtype/Type1/BaseFont/Helvetica-Bold/Encoding/WinAnsiEncoding>>';$pdf="%PDF-1.4\n";$off=array(0);for($i=1;$i<=$m;$i++){$off[$i]=strlen($pdf);$pdf.="$i 0 obj\n{$o[$i]}\nendobj\n";}$x=strlen($pdf);$pdf.="xref\n0 ".($m+1)."\n0000000000 65535 f \n";for($i=1;$i<=$m;$i++)$pdf.=sprintf('%010d 00000 n ',$off[$i])."\n";return $pdf.'trailer <</Size '.($m+1).'/Root 1 0 R>>'."\nstartxref\n$x\n%%EOF";}}
